INSERT INTO x1(content) VALUES('But riding is my special gift, my chiefest, sole delight;'); INSERT INTO x1(content) VALUES('Just ask a wild duck can it swim, a wildcat can it fight.'); INSERT INTO x1(content) VALUES('There''s nothing clothed in hair or hide, or built of flesh or steel,'); INSERT INTO x1(content) VALUES('There''s nothing walks or jumps, or runs, on axle, hoof, or wheel,'); INSERT INTO x1(content) VALUES('But what I''ll sit, while hide will hold and girths and straps are tight:'); INSERT INTO x1(content) VALUES('I''ll ride this here two-wheeled concern right straight away at sight."'); INSERT INTO x1(x1) VALUES('merge=4,4');